import React, { useEffect } from "react";
import * as Curve from "@visx/curve";
import * as Shape from "@visx/shape";
import _ from "lodash";
import { useSpring, animated } from "react-spring";

import "../assets/css/circles.css";

function HomeAnimation(props) {
  // In pixels
  let period = 100;
  let amplitude = 40;

  let width = 30 * Math.PI;
  let height = 100;

  const springData = useSpring({ inputStep: 0, from: { inputStep: 100 } });
  let calculateData = ({ value }) => {
    console.log("called");
    let newData = [];

    _.times(width, (step) => {
      let transformedStep = step + value;
      let result = amplitude * Math.sin((Math.PI / period) * transformedStep);
      newData.push([step, result + 50]);
    });

    return newData;
  };

  return (
    <animated.svg width={width} height={height}>
      <Shape.LinePath
        curve={Curve.curveCatmullRom}
        data={calculateData(springData.inputStep)}
        stroke="black"
        strokeWidth={3}
      />
    </animated.svg>
  );
}

export default HomeAnimation;
